mapper.select:
select message_id messageId,conversation_id conversationId,message_role messageRole,content,
  metadata_json metadataJson,create_time createTime
from biz_ai_message
where conversation_id=#{conversationId} and user_id=#{userId}
order by message_id desc limit #{limit}

select action_request_id actionRequestId,action_code actionCode,status,result_json resultJson
from biz_ai_action_request
where conversation_id=#{conversationId} and user_id=#{userId}
